#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int N=5e5+5;
int n;
ll m,a[N];
int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    cin>>n>>m;
    for(int i=1;i<=n;i++)cin>>a[i];
    sort(a+1,a+n+1);
    int ans=0,l=1;
    ll sum=0;
    for(int r=1;r<=n;r++){
        sum+=a[r];
        while(l<r&&(ll)(r-l+1)*a[r]-sum>m)sum-=a[l++];
        ans=max(ans,r-l+1);
    }
    cout<<ans;
    return 0;
}
